/**
 * Konnect payment process (compiled AMD module).
 *
 * @module     paygw_konnect/gateways_modal
 * @copyright  2026 MakremJebali
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define('paygw_konnect/gateways_modal', [], function() {
    return {
        process: function(component, paymentArea, itemId, description) {
            var url = M.cfg.wwwroot + '/payment/gateway/konnect/pay.php'
                + '?component=' + encodeURIComponent(component)
                + '&paymentarea=' + encodeURIComponent(paymentArea)
                + '&itemid=' + encodeURIComponent(itemId)
                + '&description=' + encodeURIComponent(description)
                + '&sesskey=' + encodeURIComponent(M.cfg.sesskey);

            window.location.href = url;

            // The browser is leaving this page, so keep the modal spinner up.
            return new Promise(function() {
                return;
            });
        }
    };
});
